import java.util.List;

/**
 * A class representing plants in the simulation. It extends
 * the abstract class Species
 *
 * @version 2022.02.28
 */
public class Plant extends Species
{
    // The plant's maximum health
    private int maxHealth;
    // The probability that the plant's health grows
    private static final double GROWING_PROBABILITY = 0.1;
    // Keep track of the plant's health
    private int currentHealth;
    // true if the current season is Spring
    private boolean isSpring;
    // true if the plant can regrow, needs at least one season till it is true again
    private boolean canRegrow;
    // true if plant appears dead due to temperature circumstances
    private boolean deadDueTemperature;

    /**
     * Create an instance of Plant
     *
     * @param field (Field) The field currently occupied.
     * @param location (Location) The location within the field.
     * @param name (String) The name of the plant
     * @param maximumTemperature (int) The maximum temperature that the plant can withstand
     * @param minimumTemperature (int) The minimum temperature that the plant can withstand
     * @param nutritionalValue (int) The nutritional value given to the specie that eats this plant
     * @param reproductionProbability (double) The probability that this plant will reproduce
     * @param maxHealth (int) The plant's maximum health
     */
    public Plant(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxHealth)
    {
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
        this.maxHealth = maxHealth;
        currentHealth = maxHealth;
        isSpring = true;
        canRegrow = true;
        deadDueTemperature = false;
    }

    /**
     * Imitate a plant's step by doing the following:
     * 1) if the plant can't survive the temperature, then it dies
     * 2) else if the time is day:
     *      i) if the plant is dead, and it's spring, and the temperature is suitable,
     *         then grow back
     *      ii) else if the plant is alive, then
     *          a) increase max health by 1 if it lived for a year
     *          b) reproduce and grow
     *
     * @param newPlants (List<Species>) A list to return the new plants created.
     * @param isNight (boolean) true if it is night in the simulation
     * @param temperature (int) The current temperature of the simulation
     * @param yearPassed (boolean) True if a year has passed in the simulation
     */
    public void act(List<Species> newPlants, boolean isNight, int temperature, boolean yearPassed)
    {
        // 1)
        if (! deadDueTemperature && ! survivesTemperature(temperature))
        {
            setDead();
        }
        // 2)
        else if (! isNight)
        {
            // i)
            if (deadDueTemperature && survivesTemperature(temperature) && isSpring) {
                regrow();
            }
            // ii)
            else if (! deadDueTemperature) {
                // a)
                if (yearPassed) {
                    maxHealth++;
                }
                // b)
                reproduce(newPlants);
                grow();
            }
        }
    }

    /**
     * Add a new plant in a free neighbouring location if the two
     * following conditions are met:
     * 1- The production probability meets the random number
     * 2- There is a free adjacent location.
     *
     * @param newPlants (list<Species>)A list to return the new plant
     */
    protected void reproduce(List<Species> newPlants)
    {
        if (rand.nextDouble() <= getReproductionProbability())
        {
            Field field = getField();
            if (field != null)
            {
                List<Location> free = field.getFreeAdjacentLocations(getLocation());

                if (free.size() > 0) {
                    Location loc = free.remove(0);
                    Plant newPlant = new Plant(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxHealth);
                    newPlant.setIsSpring(isSpring);
                    newPlants.add(newPlant);
                }
            }
        }
    }

    /**
     * The plant dies because of the temperature or because it was eaten.
     * Its location in the field is cleared, but it still remembers its field and location
     */
    protected void setDead()
    {
        if(getLocation() != null) {
            deadDueTemperature = true;
            canRegrow = false; // set to false because if left as true, it could regrow the next step
            getField().clear(getLocation());
        }
    }

    /**
     * The dead plant is placed back in the field if its previous location is empty and can regrow, otherwise do nothing.
     * If it grows, then it grows back to full health.
     */
    private void regrow()
    {
        if(getField().getObjectAt(getLocation()) == null && canRegrow) {
            deadDueTemperature = false;
            getField().place(this, getLocation());
            currentHealth = maxHealth;
        }
    }

    /**
     * Increase the plant's health by one if the random number meets the growing probability
     */
    private void grow()
    {
        if (currentHealth < maxHealth && rand.nextDouble() <= GROWING_PROBABILITY) {
            currentHealth++;
        }
    }

    /**
     * The effect of getting eaten by an animal.
     * Decrement currentHealth by one, and set dead if the current health is less than 1.
     */
    public void isEaten()
    {
        currentHealth--;

        if (currentHealth <= 0)    {
            super.setDead();
        }
    }

    /**
     * If isSpring is true, then change it to false, vice versa.
     *Also, set canRegrow as true because at least a season has passed since the plant died.
     */
    public void toggleIsSpring()
    {
        isSpring = ! isSpring;
        canRegrow = true;
    }

    /**
     * @return (boolean) true if the current season is spring, false otherwise.
     */
    public boolean getIsSpring()
    {
        return isSpring;
    }

    /**
     * Set the isSpring value to the given parameter
     *
     * @param spring (boolean) true if it is spring, false otherwise.
     */
    private void setIsSpring(boolean spring)
    {
        isSpring = spring;
    }
}

import java.util.List;
import java.util.ArrayList;

/**
 * A class representing the characteristics of a predator.
 * They are different from other animals because they eat any other
 * animal or predator whose strength is weaker.
 *
 * A horde of weaker predators can kill and eat a stronger predator.
 *
 *
 * @version 2022.03.01
 */
public class Predator extends Animal
{
    // The predator's strength, if it is strong enough it can attack other predators
    private final int strength;

    /**
     * Create a new predator with given specifications.
     *
     * @param strength (int) the predator's strength
     * @param field (Field) the field where the simulation takes place
     * @param location (Location) the Location at which the predator should appear
     * @param name (String) the predator's name (its species' name)
     * @param maximumTemperature (int) the maximum temperature the predator can survive to
     * @param minimumTemperature (int) the minimum temperature an predator can survive to
     * @param nutritionalValue (int) the predator's nutritional value
     * @param reproductionProbability (double) the probability that the predator reproduces at each step after a given minimum breeding age
     * @param maxAge (int) the predator's life expectancy
     * @param breedingAge (int) the age at which predator can start to reproduce
     * @param maxLitterSize (int) the maximum number of children the predator can have in one reproduction
     * @param randomAge (boolean) whether or not predator should be created with a random age
     * @param hibernates (boolean) whether or not predator is able to hibernate
     * @param isNocturnal (boolean) whether or not predator is more active at night
     */
    public Predator (int strength, Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize,  boolean randomAge, boolean hibernates, boolean isNocturnal)
    {
        // call to the constructor of the Animal class
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability, maxAge, breedingAge, maxLitterSize, randomAge, hibernates, isNocturnal);

        this.strength = strength;
    }

    /**
     * A predator's movement. It first checks if it attacked by a horde of another species of predators. If it is the case,
     * it dies and execution stops. If not, it first tries to reproduce, then to find a prey to eat in the neighboring cells,
     * and finally to move to either the cell the prey he ate was occupying or another free adjacent cell. If no adjacent cell
     * is available, it dies of overcrowding.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     */
    protected void makeMove(List<Species> newSpecies)
    {
        ArrayList<Animal> neighboringAnimals = getNeighboringAnimalsList();
        checkForAttack(neighboringAnimals);

        if (isAlive()) {
            if (canReproduce(neighboringAnimals)){
                reproduce(newSpecies);
            }

            // Move towards a source of food if found.
            Location newLocation = null;
            if (isNotFull()) {
                newLocation = findFoodAndEat(neighboringAnimals);
            } 

            if(newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

    /**
     * Tries to find a prey in one of the neighboring cell. If a prey is found, it is eaten and its location is returned.
     *
     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
     * @return (Location) the location of the eaten prey, null if no prey was found.
     */
    private Location findFoodAndEat(ArrayList<Animal> neighboringAnimals)
    {
        for (Animal animal : neighboringAnimals) {
            if(!(animal instanceof Predator)){
                animal.setDead();
                foodLevel += animal.getNutritionalValue();
                return animal.getLocation();
            }
        }
        // No food found
        return null;
    }

    /**
     * Check if predator if under attack from a horde of another species of predator. If a horde is attacking it and the horde's strength
     * is greater than the predator's one, the horde members eat it.
     *
     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
     */
    private void checkForAttack(ArrayList<Animal> neighboringAnimals)
    {
        ArrayList<Predator> hordeMembers = new ArrayList<>();

        for (int i =0; i < neighboringAnimals.size(); i++)
        {
            if (neighboringAnimals.get(i) instanceof Predator) {

                Predator neighboringPredator = (Predator)neighboringAnimals.get(i);
                String nameOfInvestigatedHorde = neighboringPredator.getName();

                if(! this.getName().equals(nameOfInvestigatedHorde))
                {
                    int totalHordeStrength =  neighboringPredator.getStrength();

                    hordeMembers.add(neighboringPredator);
                    for (int j =0; j < neighboringAnimals.size(); j++) {
                        if (nameOfInvestigatedHorde.equals(neighboringAnimals.get(j).getName())) {
                            Predator predatorObject = (Predator)neighboringAnimals.get(i);
                            totalHordeStrength += predatorObject.getStrength();
                            hordeMembers.add(predatorObject);
                        }
                    }
                    if (totalHordeStrength > strength) {
                        attackedByHorde(hordeMembers);
                        break;
                    } else {
                        hordeMembers.clear();
                    }
                }
            }
        }
    }

    /**
     * Animal is under attack by a horde whose strength is greater than its own. It is eaten by the horde and dies. Its nutritional value
     * is therefore shared
     *
     * @param hordeMembers (ArrayList<Predator>) List of the predators constituting the horde.
     */
    private void attackedByHorde(ArrayList<Predator> hordeMembers)
    {
        // Sharing predator's nutritional value amongst the various horde members.
        int foodLevelAddedToEachHordeMember = this.getNutritionalValue() / hordeMembers.size();
        for (Predator predator : hordeMembers) {
            predator.incrementFoodLevel(foodLevelAddedToEachHordeMember);
        }
        this.setDead();
    }

    /**
     * Creates the appropriate number of predators of the same species due to reproduction. These new predators of course share the same
     * features as their "parent" except the sex which is randomized, their age and foodLevel are not randomized.
     *
     * @param newOfThisKind (List<Species>) The list of species to which newborns must be added.
     */
    protected void reproduce(List<Species> newOfThisKind)
    {
        Field field = getField();
        if (field != null)
        {
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = numberOfBirths();
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Predator young = new Predator(strength, field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), getMaxAge(), getBreedingAge(), getMaxLitterSize(),false, getHibernates(), getIsNocturnal());
                newOfThisKind.add(young);
            }
        }
    }

    /**
     * Returns the predator's strength, public so that other predators can consult the strength of a pontential horde this predator could
     * be a part of.
     *
     * @return (int) the predator's strength.
     */
    public int getStrength() {
        return strength;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Iterator;

/**
 * A class representing shared characteristics of animals,
 * could be initialised for prey animals.
 *
 * @version 2022.02.28
 */

public class Animal extends Species
{
    // Fields defining a special kind of animal, they can not be changed after initialization

    // The age at which an animal can start to breed.
    private final int breedingAge;
    // The age to which an animal can live.
    private final int maxAge;
    // The maximum number of births at once.
    private final int maxLitterSize;
    // true if the animal's sex if female
    private final boolean isFemale;
    // true if the animal hibernates during cold temperatures
    private final boolean hibernates;
    // true if the animal is active at night
    private final boolean isNocturnal;
    // the number of steps that should pass until an animal in hibernation moves
    private static final int STAY_STEPS = 10;

    // Fields prone to change during the animal's life

    // The animal's food level
    protected int foodLevel;
    // number of steps where the animal is in hibernation
    private int hiberSteps;
    // true if the animal is currently hibernating
    private boolean inHibernation;
    // The animal's age.
    private int age;

    /**
     * Create a new animal with given specifications. An animal can be created with random age (or start at age 0) and
     * with a random foodLevel.
     *
     * @param field (Field) the field where the simulation takes place
     * @param location (Location) the Location at which the animal should appear
     * @param name (String) the animal's name (its species' name)
     * @param maximumTemperature (int) the maximum temperature the animal can survive to
     * @param minimumTemperature (int) the minimum temperature an animal can survive to
     * @param nutritionalValue (int) the animal's nutritional value
     * @param reproductionProbability (double) the probability that the animal reproduces at each step after a given minimum breeding age
     * @param maxAge (int) the animal's life expectancy
     * @param breedingAge (int) the age at which animal can start to reproduce
     * @param maxLitterSize (int) the maximum number of children the animal can have in one reproduction
     * @param randomAge (boolean) whether an animal should be created with a random age
     * @param hibernates (boolean) whether an animal is able to hibernate
     * @param isNocturnal (boolean) whether an animal is more active at night
     */
    public Animal(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize, boolean randomAge, boolean hibernates, boolean isNocturnal)
    {
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);

        this.breedingAge = breedingAge;
        this.maxAge = maxAge;
        this.maxLitterSize = maxLitterSize;
        this.isFemale = randomSex();
        this.hibernates = hibernates;
        this.isNocturnal = isNocturnal;
        // Default value is nutritionalValue to simulate the nutriment apart from the mother's milk/ other parental feeding.
        this.foodLevel = randomFoodLevel();
        inHibernation = false;
        hiberSteps = 0;

        if (randomAge) {
            age = rand.nextInt(maxAge);
        } else {
            age = 0;
        }
    }

    /**
     * Imitate an animal's step by doing the following:
     * 1) increment the animal's age if a year has passed.
     * 2) if the animal is alive, then:
     *      i) check if the animal should hibernate.
     *      ii) if the animal is in hibernation, then:
     *          a) if it passed STAY_STEPS steps without moving, then move and increment hunger.
     *          b) increment hiberSteps.
     *      iii) if the animal can't withstand the current temperature, then it dies.
     *      iv) if the animal is not in hibernation, then:
     *          a) if it is night and the animal is nocturnal, then move.
     *          b) if it is day, then all animals move and increment hunger.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     * @param isNight (boolean) true if it is night in the simulation
     * @param temperature (int) the current temperature of the simulation
     * @param yearPassed true if a year has passed in the simulation
     */
    public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed)
    {
        // 1)
        if (yearPassed) {
            incrementAge();
        }

        // 2)
        if(isAlive())
        {
            // i)
            checkHibernation(temperature);

            // ii)
            if (inHibernation)
            {
                // a)
                if (hiberSteps % STAY_STEPS == 0)   {
                    makeMove(newSpecies);
                    incrementHunger();
                }
                // b)
                incrementHiberSteps();
            }
            // iii)
            else if (! survivesTemperature(temperature))
            {
                setDead();
            }
            // iv)
            else
            {
                // a)
                if (isNight && isNocturnal) {
                    makeMove(newSpecies);
                }
                // b)
                else if (! isNight) {
                    makeMove(newSpecies);
                }
                if  (! isNight) {
                    incrementHunger();
                }
            }
        }
    }

    /**
     * An animal's movement. It first tries to reproduce, then to eat if a plant is in one of the neighboring cells and finally to move
     * if an adjacent cell is available. If no adjacent cell is available, it dies of overcrowding.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     */
    protected void makeMove(List<Species> newSpecies)
    {
        ArrayList<Animal> neighboringAnimalsList = getNeighboringAnimalsList();

        if (canReproduce(neighboringAnimalsList)) {
            reproduce(newSpecies);
        }

        // Eats if it is possible
        if (isNotFull()) {
            findFoodAndEat();
        }

        // Find a free location in adjacent cells
        Location newLocation = getField().freeAdjacentLocation(getLocation());

        // See if it was possible to move.
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            // Overcrowding.
            setDead();
        }
    }

    /**
     * Returns a list of animals located in neighboring cells.
     *
     * @return (ArrayList) list of neighboring animals
     */
    protected ArrayList<Animal> getNeighboringAnimalsList()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> locationIterator = adjacent.iterator();

        ArrayList<Animal> neighboringAnimals = new ArrayList<>();
        while (locationIterator.hasNext())
        {
            Location where = locationIterator.next();
            Species species = field.getObjectAt(where);

            if (species instanceof Animal) {
                Animal neighboringAnimal = (Animal) species;
                if (neighboringAnimal.isAlive()) {
                    neighboringAnimals.add(neighboringAnimal);
                }
            }
        }
        return neighboringAnimals;
    }

    /**
     * Increase the age. This could result in the animal's death.
     */
    protected void incrementAge()
    {
        age++;
        if(age > maxAge) {
            setDead();
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * @return (boolean) true if the animal is not full and therefore can eat and false if it is full.
     */
    protected boolean isNotFull()
    {
        return foodLevel < getNutritionalValue()*1.5;
    }

    /**
     * Increment hiberSteps by 1
     */
    protected void incrementHiberSteps()
    {
        hiberSteps++;
    }

    /**
     * Look for plants adjacent to the current location.
     * Only the first plant is eaten.
     */
    private void findFoodAndEat()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext())
        {
            Location where = it.next();
            Species species = field.getObjectAt(where);
            if(species instanceof Plant)
            {
                Plant plantSquare = (Plant) species;
                if(plantSquare.isAlive()) {
                    plantSquare.isEaten();
                    incrementFoodLevel(plantSquare.getNutritionalValue());
                    break;
                }
            }
        }
    }

    /**
     * If the animal is a female, check if a male of the same species is in one of the neighboring cells. If it is the case, animal is able to reproduce
     *  and should go to the cel where the male is.
     *  Note: The task of reproducing is handled only by females so that the same reproduction can not happen twice in the same simulator step.
     *
     * @param  neighboringAnimalsList (ArrayList<Animal>) Array List of the Animal objects located in neighboring cells.
     * @return (boolean) if animal can reproduce.
     *
     */
    protected boolean canReproduce(ArrayList<Animal> neighboringAnimalsList)
    {
        // task to reproduce is handed to women only so that the same reproduction does not happen twice
        if (this.isFemale)
        {
            for (Animal neighbor : neighboringAnimalsList) {
                if (!neighbor.isFemale && neighbor.getName().equals(this.getName())) {
                    // The neighbor is a male of the same species
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Creates the appropriate number of animals of the same species. These new animals of course share the same features as their "parent"
     * except the sex which is randomized,  their age and foodLevel are not randomized.
     *
     * @param  speciesInSimulation (List<Species>) List of Species objects in the simulation for the newborns to be added to it.
     */
    protected void reproduce(List<Species> speciesInSimulation)
    {
        Field field = getField();
        if (field != null)
        {
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = numberOfBirths();
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Animal young = new Animal(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxAge, breedingAge, maxLitterSize,false, hibernates, isNocturnal);
                speciesInSimulation.add(young);
            }
        }
    }

    /**
     * Returns a random boolean to randomize the sex of newborns.
     *
     * @return true if female, otherwise false (male)
     */
    private boolean randomSex()
    {
        return rand.nextDouble() <= 0.5;
    }

    /**
     * Return a random foodLevel more than the animal's nutritional value divided by half.
     *
     * @return (int) the foodLevel.
     */
    private int randomFoodLevel()
    {
        int lowBound = getNutritionalValue()/2;
        return rand.nextInt(lowBound) + lowBound;
    }

    /**
     * Generate a number representing the number of births, if it can breed.
     *
     * @return (int) The number of births (can be zero).
     */
    protected int numberOfBirths()
    {
        int births = 0;
        if(canGiveBirth() && rand.nextDouble() <= getReproductionProbability()) {
            births = rand.nextInt(maxLitterSize) + 1;
        }
        return births;
    }

    /**
     * An animal can give birth if it has reached the minimal breeding age.
     */
    protected boolean canGiveBirth()
    {
        return age >= breedingAge;
    }

    /**
     * Check if the animal should be in hibernation.
     *
     * Change inHibernation to true if the animal can hibernate
     * and the current temperature is less than or equal the
     * minimum temperature of the animal + 5
     *
     * @param currentTemperature (int) the current temperature of the simulation
     */
    protected void checkHibernation(int currentTemperature)
    {
        if (hibernates && currentTemperature <= getMinimumTemperature() + 5)  {
            inHibernation = true;
        }
        else {
            inHibernation = false;
            hiberSteps = 0;
        }
    }

    /**
     * @return (int) The maximum age to which an animal can live
     */
    protected int getMaxAge ()
    {
        return maxAge;
    }

    /**
     * @return (int) The age at which an animal can start to breed
     */
    protected int getBreedingAge ()
    {
        return breedingAge;
    }

    /**
     * @return (int) The maximum number of births at once
     */
    protected int getMaxLitterSize ()
    {
        return maxLitterSize;
    }

    /**
     * @return (boolean) true if the animal hibernates
     */
    protected boolean getHibernates()
    {
        return hibernates;
    }

    /**
     * @return (boolean) true if the animal is active at night
     */
    protected boolean getIsNocturnal()
    {
        return isNocturnal;
    }

